package store

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"time"

	"github.com/Mxucc/StorFlow/shop/model"
)

// newID returns a new random identifier. Identifiers are generated by the
// application so that the module never depends on dialect specific sequences.
func newID() string {
	buf := make([]byte, 16)
	if _, err := rand.Read(buf); err != nil {
		// crypto/rand never fails on supported platforms; fall back to a time
		// based identifier instead of panicking.
		return fmt.Sprintf("t%016x", time.Now().UnixNano())
	}
	buf[6] = (buf[6] & 0x0f) | 0x40
	buf[8] = (buf[8] & 0x3f) | 0x80

	var out [36]byte
	hex.Encode(out[0:8], buf[0:4])
	out[8] = '-'
	hex.Encode(out[9:13], buf[4:6])
	out[13] = '-'
	hex.Encode(out[14:18], buf[6:8])
	out[18] = '-'
	hex.Encode(out[19:23], buf[8:10])
	out[23] = '-'
	hex.Encode(out[24:36], buf[10:16])
	return string(out[:])
}

const productColumns = `id, shop_id, file_id, share_id, share_password, name, description, cover, price,
	discount, discount_end, status, sales, views, props, created_at, updated_at`

// CreateProduct inserts a product.
func (s *Store) CreateProduct(ctx context.Context, p *model.Product) error {
	props, err := json.Marshal(p.Props)
	if err != nil {
		return fmt.Errorf("shop: failed to encode product props: %w", err)
	}

	now := time.Now().Unix()
	p.CreatedAt, p.UpdatedAt = now, now

	_, err = s.conn().exec(ctx, `INSERT INTO crshop_product (`+productColumns+`)
		VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
		p.ID, p.ShopID, p.FileID, p.ShareID, p.SharePassword, p.Name, p.Description, p.Cover,
		p.Price, p.Discount, p.DiscountEnd, string(p.Status), p.Sales, p.Views, string(props),
		p.CreatedAt, p.UpdatedAt)
	return wrapErr("shop: failed to create product", err)
}

// UpdateProduct persists the mutable fields of a product.
func (s *Store) UpdateProduct(ctx context.Context, p *model.Product) error {
	props, err := json.Marshal(p.Props)
	if err != nil {
		return fmt.Errorf("shop: failed to encode product props: %w", err)
	}

	p.UpdatedAt = time.Now().Unix()
	res, err := s.conn().exec(ctx, `UPDATE crshop_product SET
			name = ?, description = ?, cover = ?, price = ?, discount = ?, discount_end = ?,
			status = ?, props = ?, updated_at = ?
		WHERE id = ?`,
		p.Name, p.Description, p.Cover, p.Price, p.Discount, p.DiscountEnd, string(p.Status),
		string(props), p.UpdatedAt, p.ID)
	if err != nil {
		return wrapErr("shop: failed to update product", err)
	}
	if n, _ := res.RowsAffected(); n == 0 {
		return ErrNotFound
	}
	return nil
}

// GetProductByID returns a product by its identifier.
func (s *Store) GetProductByID(ctx context.Context, id string) (*model.Product, error) {
	return scanProduct(s.conn().queryRow(ctx, `SELECT `+productColumns+` FROM crshop_product WHERE id = ?`, id))
}

// GetProductByID reads a product through the transaction handle.
func (t *Tx) GetProductByID(ctx context.Context, id string) (*model.Product, error) {
	return scanProduct(t.queryRow(ctx, `SELECT `+productColumns+` FROM crshop_product WHERE id = ?`, id))
}

// GetProductByShareID returns the product owning an internal share. It is used
// by the share paywall to translate a share address into the product
// entitlement that unlocks it.
func (s *Store) GetProductByShareID(ctx context.Context, shareID int) (*model.Product, error) {
	return scanProduct(s.conn().queryRow(ctx,
		`SELECT `+productColumns+` FROM crshop_product WHERE share_id = ?`, shareID))
}

// GetProductByFileIDAnyShop returns a product by the folder it sells, whatever
// the shop. It is used by the deletion guard, which only cares about whether a
// folder was sold at all.
func (s *Store) GetProductByFileIDAnyShop(ctx context.Context, fileID int) (*model.Product, error) {
	return scanProduct(s.conn().queryRow(ctx, `SELECT `+productColumns+`
		FROM crshop_product WHERE file_id = ? ORDER BY sales DESC LIMIT 1`, fileID))
}

// ListProductsWithSales returns the products that have at least one sale.
func (s *Store) ListProductsWithSales(ctx context.Context, limit int) ([]*model.Product, error) {
	rows, err := s.conn().query(ctx, `SELECT `+productColumns+`
		FROM crshop_product WHERE sales > 0 ORDER BY sales DESC LIMIT ?`, capLimit(limit))
	if err != nil {
		return nil, wrapErr("shop: failed to list sold products", err)
	}
	defer rows.Close()

	res := make([]*model.Product, 0)
	for rows.Next() {
		product, err := scanProduct(rows)
		if err != nil {
			return nil, err
		}
		res = append(res, product)
	}
	return res, wrapErr("shop: failed to iterate sold products", rows.Err())
}

// FirstSaleAt returns the time of the first settled sale of a product, or 0 when
// it was never sold. Everything that existed before that moment was delivered to
// a buyer.
func (s *Store) FirstSaleAt(ctx context.Context, productID string) (int64, error) {
	var first int64
	err := s.conn().queryRow(ctx, `SELECT COALESCE(MIN(paid_at), 0) FROM crshop_order
		WHERE kind = ? AND object_id = ? AND status IN (?, ?)`,
		string(model.OrderKindProduct), productID,
		string(model.OrderStatusPaid), string(model.OrderStatusRefunded)).Scan(&first)
	if err != nil {
		return 0, wrapErr("shop: failed to query the first sale", err)
	}
	return first, nil
}

// GetProductByFileID returns the product of a folder inside a shop.
func (s *Store) GetProductByFileID(ctx context.Context, shopID string, fileID int) (*model.Product, error) {
	return scanProduct(s.conn().queryRow(ctx,
		`SELECT `+productColumns+` FROM crshop_product WHERE shop_id = ? AND file_id = ?`, shopID, fileID))
}

// ListProductsByShop returns the products of a shop. When publicOnly is set,
// only products on sale are returned.
func (s *Store) ListProductsByShop(ctx context.Context, shopID string, publicOnly bool, limit, offset int) ([]*model.Product, error) {
	query := `SELECT ` + productColumns + ` FROM crshop_product WHERE shop_id = ?`
	args := []any{shopID}
	if publicOnly {
		query += ` AND status = ?`
		args = append(args, string(model.ProductStatusOnSale))
	}
	query += ` ORDER BY created_at DESC LIMIT ? OFFSET ?`
	args = append(args, capLimit(limit), max(offset, 0))

	rows, err := s.conn().query(ctx, query, args...)
	if err != nil {
		return nil, wrapErr("shop: failed to list products", err)
	}
	defer rows.Close()

	res := make([]*model.Product, 0)
	for rows.Next() {
		p, err := scanProductRows(rows)
		if err != nil {
			return nil, err
		}
		res = append(res, p)
	}
	return res, wrapErr("shop: failed to iterate products", rows.Err())
}

// ListProductsByStatus returns products of every shop in a given status, used
// by the public discovery feed.
func (s *Store) ListProductsByStatus(ctx context.Context, status model.ProductStatus, limit, offset int) ([]*model.Product, error) {
	rows, err := s.conn().query(ctx, `SELECT `+productColumns+` FROM crshop_product WHERE status = ?
		ORDER BY sales DESC, created_at DESC LIMIT ? OFFSET ?`,
		string(status), capLimit(limit), max(offset, 0))
	if err != nil {
		return nil, wrapErr("shop: failed to list products", err)
	}
	defer rows.Close()

	res := make([]*model.Product, 0)
	for rows.Next() {
		p, err := scanProductRows(rows)
		if err != nil {
			return nil, err
		}
		res = append(res, p)
	}
	return res, wrapErr("shop: failed to iterate products", rows.Err())
}

// IncreaseProductSales records a successful sale.
func (s *Store) IncreaseProductSales(ctx context.Context, id string, delta int) error {
	_, err := s.conn().exec(ctx, `UPDATE crshop_product SET sales = sales + ?, updated_at = ? WHERE id = ?`,
		delta, time.Now().Unix(), id)
	return wrapErr("shop: failed to update product sales", err)
}

// IncreaseProductViews records a storefront view.
func (s *Store) IncreaseProductViews(ctx context.Context, id string, delta int) error {
	_, err := s.conn().exec(ctx, `UPDATE crshop_product SET views = views + ? WHERE id = ?`, delta, id)
	return wrapErr("shop: failed to update product views", err)
}

func scanProduct(row rowScanner) (*model.Product, error) {
	return scanProductRows(row)
}

func scanProductRows(row rowScanner) (*model.Product, error) {
	var (
		p     model.Product
		props string
	)
	err := row.Scan(&p.ID, &p.ShopID, &p.FileID, &p.ShareID, &p.SharePassword, &p.Name, &p.Description,
		&p.Cover, &p.Price, &p.Discount, &p.DiscountEnd, &p.Status, &p.Sales, &p.Views, &props,
		&p.CreatedAt, &p.UpdatedAt)
	if err != nil {
		return nil, wrapErr("shop: failed to query product", err)
	}

	if props != "" {
		if err := json.Unmarshal([]byte(props), &p.Props); err != nil {
			return nil, fmt.Errorf("shop: failed to decode props of product %s: %w", p.ID, err)
		}
	}
	return &p, nil
}

func capLimit(limit int) int {
	if limit <= 0 || limit > 100 {
		return 20
	}
	return limit
}
